const propInput = $input.item.json;
const inputLink = propInput.link || propInput.url || '';
const inputMsg = propInput.mensaje || propInput.text || propInput.texto || '';
let cleanUrl = decodeURIComponent(inputLink);

// 1. Extraer código corto de Facebook (ej: 1CzZAkr5xh)
let fbCode = '';
const matchFbShare = cleanUrl.match(/(?:share\/p\/|posts\/|fbid=|photo\/\?fbid=)([a-zA-Z0-9_-]+)/i);
if (matchFbShare && matchFbShare[1]) {
  fbCode = matchFbShare[1];
}

let longFbId = '';
const matchLongInit = cleanUrl.match(/(?:\/posts\/|fbid=|_|story_fbid=)(\d{10,})/i);
if (matchLongInit && matchLongInit[1]) {
  longFbId = matchLongInit[1];
}

// 2. EXTRAER DE LA PUBLICACIÓN (Scraping e Inteligencia para resolver redirección y extraer ID oculto en HTML)
let scrapedTitle = '';
let scrapedDesc = '';
if (inputLink.startsWith('http')) {
  try {
    const res = await fetch(inputLink, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'es-ES,es;q=0.9'
      },
      redirect: 'follow'
    });
    if (res.url) {
      const redirectedUrl = decodeURIComponent(res.url);
      const matchRedirectId = redirectedUrl.match(/(?:\/posts\/|fbid=|_|story_fbid=|%2Fposts%2F|%2F)(\d{10,})/i);
      if (matchRedirectId && matchRedirectId[1]) {
        longFbId = matchRedirectId[1];
      }
    }
    if (res.ok) {
      const html = await res.text();
      if (!longFbId) {
        const ogUrlMatch = html.match(/<meta[^>]*property=["']og:url["'][^>]*content=["']([^"']+)["']/i) ||
                           html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:url["']/i) ||
                           html.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i);
        if (ogUrlMatch && ogUrlMatch[1]) {
          const matchFromOg = decodeURIComponent(ogUrlMatch[1]).match(/(\d{13,17})/);
          if (matchFromOg && matchFromOg[1]) {
            longFbId = matchFromOg[1];
          }
        }
        if (!longFbId) {
          const anyIdMatch = html.match(/(?:\/|fbid=|story_fbid=|post_id=|_|%2F)(\d{13,17})(?:\/|%2F|"|'|&|\s|$)/i);
          if (anyIdMatch && anyIdMatch[1]) {
            longFbId = anyIdMatch[1];
          }
        }
        if (!longFbId) {
          const allNums = html.match(/(\d{13,17})/g);
          if (allNums && allNums[0]) {
            longFbId = allNums[0];
          }
        }
      }
      const ogTitleMatch = html.match(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["']/i) ||
                           html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:title["']/i);
      if (ogTitleMatch && ogTitleMatch[1]) scrapedTitle = ogTitleMatch[1];
      else {
        const titleTagMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
        if (titleTagMatch && titleTagMatch[1]) scrapedTitle = titleTagMatch[1];
      }
      const ogDescMatch = html.match(/<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']+)["']/i) ||
                          html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
      if (ogDescMatch && ogDescMatch[1]) scrapedDesc = ogDescMatch[1];
    }
  } catch (e) {}

  if (!scrapedTitle || scrapedTitle.toLowerCase().includes('facebook') || scrapedTitle.toLowerCase().includes('inicia sesión')) {
    try {
      const mlRes = await fetch(`https://api.microlink.io/?url=${encodeURIComponent(inputLink)}`);
      if (mlRes.ok) {
        const mlJson = await mlRes.json();
        if (mlJson.status === 'success' && mlJson.data) {
          if (mlJson.data.url && !longFbId) {
            const matchMlId = decodeURIComponent(mlJson.data.url).match(/(?:\/posts\/|fbid=|_|story_fbid=)(\d{10,})/i);
            if (matchMlId && matchMlId[1]) longFbId = matchMlId[1];
          }
          if (mlJson.data.title && !mlJson.data.title.toLowerCase().includes('facebook')) {
            scrapedTitle = mlJson.data.title;
          }
          if (mlJson.data.description && !mlJson.data.description.toLowerCase().includes('facebook')) {
            scrapedDesc = mlJson.data.description;
          }
        }
      }
    } catch (e) {}
  }
}

// 3. Unir título, descripción, slug y el MENSAJE de WhatsApp del cliente
let rawText = [scrapedTitle, scrapedDesc, inputMsg].filter(Boolean).join(' ');
if (!rawText || rawText.length < 5) {
  const matchSlug = cleanUrl.match(/\/([^\/?#]+-[^\/?#]+-[^\/?#]+)/);
  if (matchSlug && matchSlug[1]) rawText = matchSlug[1];
}

rawText = rawText
  .replace(/\| Facebook/i, '')
  .replace(/ - Facebook/i, '')
  .replace(/Inicia sesi[oó]n o reg[ií]strate para ver/i, '')
  .replace(/\.html$|\.php$|\.aspx$/i, '')
  .replace(/[-_+]/g, ' ')
  .trim();

const allWords = rawText
  .replace(/[^\w\s\u00C0-\u017F]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length >= 3 && !['https', 'http', 'facebook', 'share', 'posts', 'photo', 'propiedad', 'inmobi', 'venta', 'arriendo', 'casa', 'departamento', 'terreno', 'para', 'como', 'esta', 'este', 'esto', 'hola', 'buenas', 'tardes', 'dias', 'noches', 'informacion', 'info', 'favor', 'ayuda', 'quiero', 'busco', 'interesa', 'interesado', 'publicacion', 'link', 'enlace', 'sobre', 'aqui', 'alla', 'donde', 'tiene', 'tienen'].includes(w.toLowerCase()));

const keywords = allWords.slice(0, 4);

return [{
  json: {
    original_link: inputLink,
    fb_code: fbCode || '',
    long_fb_id: longFbId || '',
    scraped_title: scrapedTitle || '',
    scraped_desc: scrapedDesc || '',
    extracted_title: rawText || (fbCode !== rawText ? rawText : ''),
    keywords: keywords
  }
}];

const prop = $input.item.json;
const extraido = $('Extraer Título del Link').item.json;

// La fila completa viene como JSON: así no dependemos del nombre exacto de ninguna columna.
const raw = prop.raw_row || {};
const adv = prop.advisor_row || {};

// Cada dato se busca probando los nombres de columna más comunes en Odoo (estándar y personalizados)
const titulo   = raw.title ?? raw.name ?? 'Propiedad';
const precio   = Number(raw.price ?? raw.selling_price ?? raw.expected_price ?? raw.list_price ?? 0);
const estado   = raw.state ?? raw.status ?? '';
const habs     = raw.bedrooms ?? raw.rooms ?? raw.habitaciones ?? null;
const banos    = raw.bathrooms ?? raw.bathroom ?? raw.banos ?? null;
const ciudad   = raw.city ?? raw.ciudad ?? raw.location ?? '';
const areaM2   = raw.living_area ?? raw.area ?? raw.m2 ?? raw.square_meters ?? raw.total_area ?? raw.superficie ?? raw.metros ?? null;
const asesorNom = adv.name ?? adv.display_name ?? 'Equipo Inmobi';
const asesorTel = adv.phone ?? adv.mobile ?? adv.telefono ?? '';

const precioFmt = new Intl.NumberFormat('es-EC', { style: 'currency', currency: 'USD' }).format(precio);

// Ficha en texto plano (sin markdown), con iconos solo donde corresponde
const lineas = [];
lineas.push('🏡 ' + titulo);
if (ciudad) lineas.push('📍 Ciudad: ' + ciudad);
if (prop.tipo_propiedad) lineas.push('🏢 Tipo: ' + prop.tipo_propiedad);
lineas.push('💰 Precio: ' + precioFmt);

const specs = [];
if (habs)   specs.push('🛏️ ' + habs + ' habitaciones');
if (banos)  specs.push('🚿 ' + banos + ' baños');
if (areaM2) specs.push('📐 ' + areaM2 + ' m²');
if (specs.length) lineas.push(specs.join(' | '));

if (asesorTel) lineas.push('👤 Asesor: ' + asesorNom + ' (' + asesorTel + ')');
else lineas.push('👤 Asesor: ' + asesorNom);
lineas.push('🔖 Estado: ' + (estado === 'available' ? 'Disponible' : 'Vendida/Reservada'));

return [{
  json: {
    encontrado: true,
    property_id: Number(prop.id),
    titulo_encontrado: titulo,
    titulo_buscado: extraido.extracted_title || extraido.fb_code,
    precio: precio,
    precio_formateado: precioFmt,
    ciudad: ciudad,
    estado: estado,
    habitaciones: habs,
    banos: banos,
    area_m2: areaM2,
    asesor_nombre: asesorNom,
    asesor_telefono: asesorTel,
    ficha_formateada: lineas.join('\n'),
    link_original: extraido.original_link
  }
}];

const extraido = $('Extraer Título del Link').item.json;
const prop = $input.item.json || {};
const infoPost = prop.fb_post_message || [extraido.scraped_title, extraido.scraped_desc].filter(Boolean).join(' ') || '';

if (infoPost && infoPost.length > 10 && !infoPost.toLowerCase().includes('inicia sesión')) {
  return [{
    json: {
      encontrado: false,
      requiere_busqueda_tool: true,
      property_id: 0,
      info_publicacion: infoPost,
      link_original: extraido.original_link,
      mensaje: `Información de la publicación en Facebook:
"${infoPost}"

(INSTRUCCIÓN DEL SISTEMA PARA EL BOT: Esta publicación existe pero aún no tiene ID de propiedad asignado. Utiliza de inmediato tu herramienta de búsqueda de propiedades / buscar_propiedades con las palabras clave, sector, m2 o precio extraídos del texto anterior para encontrar la propiedad y mostrársela al cliente).`
    }
  }];
} else {
  return [{
    json: {
      encontrado: false,
      requiere_busqueda_tool: false,
      property_id: 0,
      titulo_buscado: extraido.extracted_title || extraido.fb_code,
      link_original: extraido.original_link,
      mensaje: `No encontramos ninguna propiedad que coincida con el link ('${extraido.extracted_title || extraido.fb_code}'). Puede que no esté registrada en el sistema o tenga otro título.`
    }
  }];
}
